/**
 * Semente do histórico da época 2026-2027: o que já tinha acontecido antes de a
 * aplicação começar a ser usada.
 *
 * Gerado a partir dos mapas oficiais de nomeações da FPF (um ficheiro por
 * delegado) e da base de dados onde esses jogos já tinham sido importados. Vai
 * no executável porque tem de chegar a todas as máquinas — o coordenador não
 * tem de importar competição nenhuma nem repetir trabalho.
 */

export interface ClubeSemente {
  nome: string
}

export interface RecintoSemente {
  nome: string
  morada: string | null
  lat: number | null
  lng: number | null
  confirmado: boolean
}

export interface CompeticaoSemente {
  fpfCompetitionId: number
  seasonId: number
  seasonDescricao: string | null
  nome: string
  organizacao: string | null
  nivelMinimo: string | null
  usaDelegadoAssistente: boolean
  todosComDelegado: boolean
}

export interface JogoSemente {
  competicaoFpf: number
  seasonId: number
  fixtureId: number | null
  fase: string | null
  serie: string | null
  jornada: string | null
  dataHora: string | null
  estado: string
  casa: string
  fora: string
  recinto: string | null
  recintoTextoFpf: string | null
}

export interface NomeacaoSemente {
  competicaoFpf: number
  fixtureId: number | null
  casa: string
  fora: string
  papel: string
  delegadoNumero: string
  /** O delegado errado que se espera encontrar; só esse é substituído. */
  substituirNumero: string | null
}

